node <<'NODE'
const fs = require('node:fs');
const wait = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
  const page = targets.find(t => t.type === 'page');
  if (!page) throw new Error('No Chrome page target');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let id = 0;
  const pending = new Map();
  const errors = [];
  ws.onmessage = event => {
    const msg = JSON.parse(event.data);
    if (msg.method === 'Runtime.exceptionThrown') errors.push(msg.params.exceptionDetails.text);
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  };
  const send = (method, params = {}) => new Promise(resolve => {
    const requestId = ++id;
    pending.set(requestId, resolve);
    ws.send(JSON.stringify({ id: requestId, method, params }));
  });
  await send('Page.enable'); await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });
  await wait(1600);
  let result = await send('Runtime.evaluate', { expression: `(() => { document.getElementById('playBtn').click(); return {title:document.title,started:document.getElementById('startScreen').classList.contains('dismiss'),hud:!!document.getElementById('healthFill'), mobileControls:getComputedStyle(document.getElementById('mobileControls')).display, viewport:[innerWidth,innerHeight], overflow:[document.documentElement.scrollWidth,document.documentElement.scrollHeight]}; })()`, returnByValue: true });
  const checks = result.result.result.value;
  await wait(1800);
  const shot = await send('Page.captureScreenshot', { format: 'jpeg', quality: 72, captureBeyondViewport: false });
  fs.writeFileSync('/tmp/opencode/emberfall-mobile-game.jpg', Buffer.from(shot.result.data, 'base64'));
  console.log(JSON.stringify({ checks, errors, screenshot: '/tmp/opencode/emberfall-mobile-game.jpg' }, null, 2));
  ws.close();
})().catch(err => { console.error(err); process.exitCode = 1; });
